from datetime import datetime

class TestAccessGatewayFilter(unittest.TestCase):
    def test_get_jwt_user_valid_token(self):
        filter = AccessGatewayFilter()
        request = {
            'headers': {
                'Authorization': {
                    'user': {'name': 'user1'},
                    'jwt': 'user1' + str(datetime.date.today())
                }
            }
        }
        expected = {'user': {'name': 'user1'}}
        self.assertEqual(filter.get_jwt_user(request), expected)

    def test_get_jwt_user_invalid_token(self):
        filter = AccessGatewayFilter()
        request = {
            'headers': {
                'Authorization': {
                    'user': {'name': 'user1'},
                    'jwt': 'invalid_token'
                }
            }
        }
        self.assertIsNone(filter.get_jwt_user(request))

    def test_get_jwt_user_no_token(self):
        filter = AccessGatewayFilter()
        request = {
            'headers': {
                'Authorization': {
                    'user': {'name': 'user1'}
                }
            }
        }
        self.assertIsNone(filter.get_jwt_user(request))

if __name__ == '__main__':
